function validate([matrix]) {
  if (!Array.isArray(matrix) || matrix.length < 1 || matrix.length > 100) return 'matrix needs 1 to 100 rows.';
  const n = matrix.length;
  for (const line of matrix) {
    if (!Array.isArray(line) || line.length !== n) return 'matrix must be square (n rows of n values).';
    if (line.some(v => !Number.isInteger(v) || v < -100 || v > 100)) return 'Each value is an integer from -100 to 100.';
  }
  return null;
}

