function minFallingPathSum(matrix) {
  const n = matrix.length;
  let dp = matrix[0].slice();

  for (let row = 1; row < n; row++) {
    const next = new Array(n);
    for (let col = 0; col < n; col++) {
      let best = dp[col];
      if (col > 0) {
        best = Math.min(best, dp[col - 1]);
      }
      if (col < n - 1) {
        best = Math.min(best, dp[col + 1]);
      }
      next[col] = matrix[row][col] + best;
    }
    dp = next;
  }
  return Math.min(...dp);
}

