function minFallingPathSum(matrix) {
  const n = matrix.length;
  // Top-down: the cheapest path starting at (r, c) and falling to the bottom, memoised.
  const memo = new Map();
  const walk = (r, c) => {
    if (c < 0 || c >= n) return Infinity;
    if (r === n - 1) return matrix[r][c];
    const key = r * n + c;
    if (!memo.has(key)) memo.set(key, matrix[r][c] + Math.min(walk(r + 1, c - 1), walk(r + 1, c), walk(r + 1, c + 1)));
    return memo.get(key);
  };
  let answer = Infinity;
  for (let c = 0; c < n; c++) answer = Math.min(answer, walk(0, c));
  return answer;
}

