function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 5);
  const span = size === 'large' ? 100 : (rand() < 0.5 ? 100 : 3);
  const matrix = [];
  for (let r = 0; r < n; r++) {
    const line = [];
    for (let c = 0; c < n; c++) line.push(Math.floor(rand() * (2 * span + 1)) - span);
    matrix.push(line);
  }
  return [matrix];
}
